def semver_sort(versions):
    def parse_key(version):
        # Strip build metadata
        plus_idx = version.find('+')
        if plus_idx != -1:
            main_and_pre = version[:plus_idx]
        else:
            main_and_pre = version

        dash_idx = main_and_pre.find('-')
        if dash_idx != -1:
            main = main_and_pre[:dash_idx]
            pre = main_and_pre[dash_idx+1:]
        else:
            main = main_and_pre
            pre = None

        parts = main.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        if pre is None:
            has_pre_flag = 1
            identifiers_key = []
        else:
            has_pre_flag = 0
            identifiers = pre.split('.')
            identifiers_key = []
            for ident in identifiers:
                if ident.isdigit():
                    identifiers_key.append((0, int(ident)))
                else:
                    identifiers_key.append((1, ident))

        return (major, minor, patch, has_pre_flag, identifiers_key)

    return sorted(versions, key=parse_key)

